<template>
  <div class="wrapper" v-if="started">
    <div class="title">
      {{ text }}
    </div>
    <div class="container">
      <div class="center">
        <vue-ellipse-progress id="timer-example" :progress="secondsProgress" :determinate="determinate" :color="colorProg"
          :legendValue="secondsProgress" empty-color="#fff" :dot="{
            size: 10,
            backgroundColor: 'white',
            width: '1px',
          }" thickness="3" emptyThickness="5" :size="180" dash="strict 60 0.8" lineMode="in-over"
          :emptyColorFill="emptyColorFill" :legend="false" legendClass="legend-custom-style" fontSize="1.5rem"
          font-color="white" animation="loop 100 100" :loading="loading" :no-data="noData" fontSize="4rem">
          <div slot="legend-caption">
            <div class="caption">{{ rounds }}/{{ roundsMax }}</div>
          </div>
        </vue-ellipse-progress>
      </div>
  
      <div class="top">
        <transition name="bounce">
          <div v-if="showbtn[0]" class="keyboard-button">{{ show1 ? this.chosenKey[0] : '?' }}</div>
        </transition>
      </div>
      <div class="right">
        <transition name="bounce">
          <div v-show="showbtn[1]" class="keyboard-button">{{ show2 ? this.chosenKey[1] : '?' }}</div>
        </transition>
      </div>
      <div class="bottom">
        <transition name="bounce">
          <div v-show="showbtn[2]" class="keyboard-button">{{ show3 ? this.chosenKey[2] : '?' }}</div>
        </transition>
      </div>
      <div class="left">
        <transition name="bounce">
          <div v-show="showbtn[3]" class="keyboard-button">{{ show4 ? this.chosenKey[3] : '?' }}</div>
        </transition>
      </div>
  
    </div>
  </div>
  <!-- <div class="container">
    <div class="keyboard-button-1"></div>
    <div class="time-counter">

    </div>
  </div> -->
</template>

<script>
import $ from 'jquery'
export default {
  name: "timeCounter",
  props: {
    activeCases: {
      type: Number,
      required: true
    },
  },
  data() {
    return {
      started: false,
      circles: [],
      show1: true,
      show2: false,
      show3: false,
      show4: false,
      showbtn: [true,true,true,true],
      time: 15,
      text: '',
      colorProg: '#ffd905',
      currentKey: null,
      currentKeyId: null,
      keys: ['W', 'A', 'S', 'D'],
      rounds: 9,
      chosenKey: [],
      roundsMax: 9,
      secondsProgress: 0,
      secondsLegend: 0,
      millisecondsValue: 0,
      emptyColorFill: {
        radial: true,
        colors: [
          {
            color: "#000",
            offset: "50",
            opacity: "0.2",
          },
          {
            color: "#000",
            offset: "50",
            opacity: "0.15",
          },
          {
            color: "#000",
            offset: "70",
            opacity: "0.15",
          },
          {
            color: "#000",
            offset: "70",
            opacity: "0.1",
          },
          {
            color: "#000",
            offset: "90",
            opacity: "0.1",
          },
          {
            color: "transparent",
            offset: "90",
            opacity: "0.1",
          },
          {
            color: "transparent",
            offset: "95",
            opacity: "0.1",
          },
          {
            color: "transparent",
            offset: "95",
            opacity: "0.1",
          },
        ],
      },
    }
  },
  mounted: function () {
    let self = this // AAAAAAA RAISING FOR THE SCOPEEEEEE ;3333
    window.addEventListener('message', function(event){
        var eventData = event.data;

        if (eventData.action == "startGame") {
          self.currentKey = null;
          self.currentKeyId = null;
          self.show1 = true;
          self.show2 = false;
          self.show3 = false;
          self.show4 = false;
          self.showbtn = [true,true,true,true]
          self.secondsLegend = 0
          self.secondsProgress = 0
          self.time = eventData.time;
          self.text = eventData.text;
          self.colorProg = eventData.color;
          self.rounds = eventData.rounds;
          self.roundsMax = eventData.rounds;
          self.roundsMax = eventData.rounds;
          clearInterval(self.msTimer2);
          clearInterval(this.msTimer)
          self.started = true;
          self.picker();
          self.msTimer2 = setInterval(() => {
            self.setTimer();
          }, 2500)
        }
    })
    window.addEventListener('keydown', (e) => {
      if (e.key.toLowerCase() == self.currentKey.toLowerCase()) {
        self.secondsLegend = ((self.currentKeyId +1) * 25) / 100 *self.time
        self.showbtn[this.currentKeyId] = false;
      } else {
        clearInterval(this.msTimer)
        self.started = false;
        $.post('http://ps-minigame/callback', JSON.stringify({
          success: false
        }));
      }
    });
  },
  methods: {
    setTimer() {
      clearInterval(this.msTimer2)
      this.msTimer = setInterval(() => {
        if (this.secondsProgress <= 25) {
          this.show1 = true;
          this.currentKey = this.chosenKey[0];
          this.currentKeyId = 0;
        } else if (this.secondsProgress <= 50 && this.secondsProgress > 25) {
          this.show2 = true;
          if (this.showbtn[this.currentKeyId] && this.currentKeyId !== 1) {
            this.secondsLegend = 0
            this.secondsProgress = 0
            clearInterval(this.msTimer);
            this.started = false;
            $.post('http://ps-minigame/callback', JSON.stringify({
              success: false
            }));
          }
          this.currentKey = this.chosenKey[1];
          this.currentKeyId = 1;
        } else if (this.secondsProgress <= 75 && this.secondsProgress > 50) {
          this.show3 = true;
          this.currentKey = this.chosenKey[2];
          this.show1 = false;
          if (this.showbtn[this.currentKeyId] && this.currentKeyId !== 2) {
            this.secondsLegend = 0
            this.secondsProgress = 0
            clearInterval(this.msTimer);
            this.started = false;
            $.post('http://ps-minigame/callback', JSON.stringify({
              success: false
            }));
          }
          this.currentKeyId = 2;
        } else if (this.secondsProgress <= 100 && this.secondsProgress > 75) {
          this.show4 = true;
          this.currentKey = this.chosenKey[3];
          if (this.showbtn[this.currentKeyId] && this.currentKeyId !== 3) {
            this.secondsLegend = 0
            this.secondsProgress = 0
            clearInterval(this.msTimer);
            this.started = false;
            $.post('http://ps-minigame/callback', JSON.stringify({
              success: false
            }));
          }
          this.currentKeyId = 3;
        }
        if (this.secondsLegend >= this.time) {
          this.rounds = this.rounds - 1
          this.secondsLegend = 0
          this.secondsProgress = 0

          this.show1 = false;
          this.show2 = false;
          this.show3 = false;
          this.show4 = false;
          for (let i = 0; i < 4; i += 1) {
            this.showbtn[i] = true
          }
          this.picker();
          this.show1 = true;
          if (this.rounds <= 0) {
            this.started = false;
            $.post('http://ps-minigame/callback', JSON.stringify({
              success: true
            }));
            clearInterval(this.msTimer)
          }
        }
        this.secondsLegend = this.secondsLegend + 0.10;
        this.secondsProgress = this.secondsLegend * 100 / this.time
      }, 100)
    },
    picker() {
      this.chosenKey = [];
      for (let i = 0; i < 4; i += 1) {
        var chosenNumber = Math.floor(Math.random() * this.keys.length);
        this.chosenKey.push(this.keys[chosenNumber])
      }
    }
  },
  destroyed: function () {
    clearInterval(this.msTimer)
  },
}
</script>
// end of script section
